import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardActions,
  CardContent,
  CircularProgress,
  Divider,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Switch,
  Typography,
} from '@mui/material';
import {
  ArrowForward as ArrowForwardIcon,
  Assessment as ReportsIcon,
  Flag as IndiaIcon,
  GpsFixed as GpsIcon,
  Public as ExportIcon,
} from '@mui/icons-material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import ApiService from '../../services/api';
import { unwrapComplianceHubPayload, complianceSectionHref, GEOTAGGED_EVIDENCE_HREF } from '../../constants/complianceHub';
import { useMsmeProfileQuery } from '../../hooks/queries/useMsmeWorkspaceQueries';
import { hasMsmeExportIntent } from '../../utils/msmeExportIntent';
import PlainLanguageLabel from '../shared/PlainLanguageLabel';
import ComplianceReadinessGrid, { ReadinessGridItem } from './ComplianceReadinessGrid';
import ComplianceReadinessActionQueue, { type PrioritizedReadinessAction } from './ComplianceReadinessActionQueue';
import { type ModuleGapBundle } from './ComplianceReadinessGapPanel';
import { buildMsmeReadinessSteps, filterPrioritizedActionsOutsideSteps } from '../../utils/buildMsmeReadinessSteps';
import MsmeReadinessChecklist from './MsmeReadinessChecklist';
import BuyerRequestInbox from './BuyerRequestInbox';
import OrchestrationRunPanel, { type OrchestrationRunSummary } from './OrchestrationRunPanel';
import ComplianceHubOnboardingGuide from './ComplianceHubOnboardingGuide';
import ComplianceOrchestrationHub from './ComplianceOrchestrationHub';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { READINESS_LOCALE_OPTIONS } from '../../i18n/readinessLocale';
import { PRODUCT_SCOPE_DISCLAIMER, PRODUCT_SCOPE_TAGLINE } from '../../constants/productScope';
import { resolveTrackItemLabel } from '../../constants/complianceTrackLocale';
import { useOrchestrationEvents } from '../../hooks/useOrchestrationEvents';

const ComplianceHubHome: React.FC = () => {
  const navigate = useNavigate();
  useOrchestrationEvents(true);
  const { locale, setLocale, strings } = useReadinessLocale();
  const profileQuery = useMsmeProfileQuery();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [overview, setOverview] = useState<Record<string, unknown> | null>(null);
  const [exportSaving, setExportSaving] = useState(false);
  const [exportFeedback, setExportFeedback] = useState<string | null>(null);

  const profile = profileQuery.data?.data;
  const exportIntent = useMemo(() => hasMsmeExportIntent(profile), [profile]);
  const [exportDraft, setExportDraft] = useState(false);

  React.useEffect(() => {
    setExportDraft(Boolean(profile?.manufacturingProfile?.exportActivity));
  }, [profile?.manufacturingProfile?.exportActivity]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceHubOverview({ period: 'annual' });
      setOverview(unwrapComplianceHubPayload<Record<string, unknown>>(res));
    } catch (e) {
      setOverview(null);
      setError(e instanceof Error ? e.message : 'Failed to load compliance overview');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const saveExportIntent = async () => {
    setExportSaving(true);
    setExportFeedback(null);
    try {
      await ApiService.updateMSMEProfile({
        manufacturingProfile: {
          ...(profile?.manufacturingProfile || {}),
          exportActivity: exportDraft,
        },
      });
      await profileQuery.refetch();
      setExportFeedback(
        exportDraft
          ? 'Export compliance unlocked — open the Global export track below.'
          : 'Export compliance hidden — you can turn it on anytime from My company → Profile.'
      );
    } catch (e) {
      setExportFeedback(e instanceof Error ? e.message : 'Unable to save export preference.');
    } finally {
      setExportSaving(false);
    }
  };

  const indiaReadiness = useMemo(
    () => (overview?.indiaReadiness || {}) as Record<string, string>,
    [overview?.indiaReadiness]
  );
  const exportReadiness = useMemo(
    () => (overview?.exportReadiness || {}) as Record<string, string>,
    [overview?.exportReadiness]
  );
  const moduleScores = useMemo(
    () => (overview?.moduleScores || {}) as Record<string, number | null>,
    [overview?.moduleScores]
  );
  const thresholds = useMemo(
    () => (overview?.thresholds || {}) as Record<string, number>,
    [overview?.thresholds]
  );
  const overallReadinessScore = overview?.overallReadinessScore as number | null | undefined;
  const indiaOverallReadinessScore = overview?.indiaOverallReadinessScore as number | null | undefined;
  const exportOverallReadinessScore = overview?.exportOverallReadinessScore as number | null | undefined;
  const exportApplicable = Boolean(overview?.exportApplicable);
  const prioritizedActions = (overview?.prioritizedActions || []) as PrioritizedReadinessAction[];
  const moduleGapDetails = (overview?.moduleGapDetails || {}) as Record<string, ModuleGapBundle>;
  const agentOrchestration = (overview?.agentOrchestration || {}) as {
    lastRuns?: Record<string, OrchestrationRunSummary>;
    recentHistory?: OrchestrationRunSummary[];
  };
  const recentOrchestrationRuns = agentOrchestration.recentHistory || [];
  const inventoryVerification = (overview?.inventoryMetadata as {
    inventoryVerificationSummary?: {
      hasProvisionalInventory?: boolean;
      provisionalTransactionCount?: number;
      provisionalEmissionsSharePct?: number;
      provisionalTransactionSharePct?: number;
    };
  } | null)?.inventoryVerificationSummary;
  const inventoryQualityHints = (overview?.inventoryQuality as { hints?: string[] } | null)?.hints || [];
  const hasProvisionalInventory = Boolean(inventoryVerification?.hasProvisionalInventory);

  const indiaGridItems: ReadinessGridItem[] = useMemo(() => [
    { key: 'brsrCore', label: resolveTrackItemLabel('brsrCore', locale, 'BRSR Core pack'), status: indiaReadiness.brsrCore, score: moduleScores.brsrCore, href: complianceSectionHref('/compliance/india', 'brsr-core'), threshold: thresholds.brsrDisclosurePrep },
    { key: 'isoAssurance', label: resolveTrackItemLabel('isoAssurance', locale, 'ISO 14064 assurance'), status: indiaReadiness.isoAssurance, score: moduleScores.isoAssurance, href: complianceSectionHref('/compliance/india', 'iso-assurance'), threshold: thresholds.isoAssurancePrep },
    { key: 'zedCertification', label: resolveTrackItemLabel('zedCertification', locale, 'MSME ZED certification'), status: indiaReadiness.zedCertification, score: moduleScores.zedCertification, href: complianceSectionHref('/compliance/india', 'zed-certification') },
    { key: 'patIntensity', label: resolveTrackItemLabel('patIntensity', locale, 'PAT / energy intensity'), status: indiaReadiness.patIntensity, score: moduleScores.patIntensity, href: complianceSectionHref('/compliance/india', 'pat-intensity'), threshold: thresholds.patReadiness },
    { key: 'sbti', label: resolveTrackItemLabel('sbti', locale, 'SBTi targets'), status: indiaReadiness.sbti, score: moduleScores.sbti, href: complianceSectionHref('/compliance/india', 'sbti-plans'), threshold: thresholds.sbtiReadiness },
    { key: 'accountingSync', label: resolveTrackItemLabel('accountingSync', locale, 'Accounting sync'), status: indiaReadiness.accountingSync, score: moduleScores.tier1DataQuality, href: complianceSectionHref('/compliance/india', 'data-sync') },
  ], [locale, indiaReadiness, moduleScores, thresholds]);

  const exportGridItems: ReadinessGridItem[] = useMemo(() => [
    { key: 'cbam', label: resolveTrackItemLabel('cbam', locale, 'CBAM'), status: exportReadiness.cbam, score: moduleScores.cbam, href: complianceSectionHref('/compliance/export', 'cbam'), threshold: thresholds.cbamFilingReady },
    { key: 'productPcf', label: resolveTrackItemLabel('productPcf', locale, 'Product PCF'), status: exportReadiness.productPcf, score: moduleScores.productPcf, href: '/compliance/product-pcf', threshold: thresholds.isoAssurancePrep },
    { key: 'csrd', label: resolveTrackItemLabel('csrd', locale, 'CSRD supplier'), status: exportReadiness.csrd, score: moduleScores.csrd, href: complianceSectionHref('/compliance/export', 'csrd-supplier'), threshold: thresholds.packReadiness },
    { key: 'cdp', label: resolveTrackItemLabel('cdp', locale, 'CDP'), status: exportReadiness.cdp, score: moduleScores.cdp, href: complianceSectionHref('/compliance/export', 'cdp'), threshold: thresholds.packReadiness },
    { key: 'gri', label: resolveTrackItemLabel('gri', locale, 'GRI 305'), status: exportReadiness.gri, score: moduleScores.gri, href: complianceSectionHref('/compliance/export', 'gri'), threshold: thresholds.packReadiness },
    { key: 'tcfd', label: resolveTrackItemLabel('tcfd', locale, 'TCFD / ISSB'), status: exportReadiness.tcfd, score: moduleScores.tcfd, href: complianceSectionHref('/compliance/export', 'tcfd-issb'), threshold: thresholds.packReadiness },
    { key: 'supplierPortal', label: resolveTrackItemLabel('supplierPortal', locale, 'Buyer questionnaires'), status: exportReadiness.supplierPortal, score: moduleScores.supplierPortal, href: complianceSectionHref('/compliance/export', 'supplier-portal'), threshold: thresholds.buyerPortal },
    { key: 'eudr', label: resolveTrackItemLabel('eudr', locale, 'EUDR'), status: exportReadiness.eudr, score: moduleScores.eudr, href: complianceSectionHref('/compliance/export', 'eudr'), threshold: thresholds.packReadiness },
    { key: 'ecovadis', label: resolveTrackItemLabel('ecovadis', locale, 'EcoVadis'), status: exportReadiness.ecovadis, score: moduleScores.ecovadis, href: complianceSectionHref('/compliance/export', 'ecovadis'), threshold: thresholds.packReadiness },
  ], [locale, exportReadiness, moduleScores, thresholds]);

  const readinessModuleKeys = useMemo(
    () => [
      ...indiaGridItems.map((item) => item.key),
      ...(exportIntent ? exportGridItems.map((item) => item.key) : []),
    ],
    [indiaGridItems, exportGridItems, exportIntent]
  );

  const checklistSteps = useMemo(
    () =>
      buildMsmeReadinessSteps({
        prioritizedActions,
        moduleGapDetails,
        moduleKeys: readinessModuleKeys,
        overallReadinessScore,
        maxSteps: 3,
      }),
    [prioritizedActions, moduleGapDetails, readinessModuleKeys, overallReadinessScore]
  );

  const supplementalPrioritizedActions = useMemo(
    () => filterPrioritizedActionsOutsideSteps(prioritizedActions, checklistSteps),
    [prioritizedActions, checklistSteps]
  );

  return (
    <Box>

      <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
        <FormControl size="small" sx={{ minWidth: 180 }}>
          <InputLabel id="readiness-locale-label">{strings.languageToggleLabel}</InputLabel>
          <Select
            labelId="readiness-locale-label"
            label={strings.languageToggleLabel}
            value={locale}
            onChange={(e) => setLocale(e.target.value as typeof locale)}
          >
            {READINESS_LOCALE_OPTIONS.map((option) => (
              <MenuItem key={option.id} value={option.id}>
                {option.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      <ComplianceHubOnboardingGuide />

      {hasProvisionalInventory && (
        <Alert
          severity="warning"
          sx={{ mb: 3 }}
          action={(
            <Button component={RouterLink} to="/operations" color="inherit" size="small">
              Review transactions
            </Button>
          )}
        >
          {inventoryVerification?.provisionalTransactionCount || 0} bill-derived inventory row
          {(inventoryVerification?.provisionalTransactionCount || 0) === 1 ? '' : 's'} (
          {inventoryVerification?.provisionalEmissionsSharePct || 0}% of emissions) are provisional.
          {inventoryQualityHints[0] ? ` ${inventoryQualityHints[0]}` : ' Verify vendor, date, GSTIN, and invoice number on source bills before assurance or BRSR filing.'}
        </Alert>
      )}

      <Alert severity="info" sx={{ mb: 3 }}>
        <Typography variant="body2">
          New to carbon reporting? Complete your{' '}
          <Button component={RouterLink} to="/carbon-footprint?section=start-assessment" size="small" sx={{ verticalAlign: 'baseline' }}>
            carbon assessment
          </Button>
          {' '}first — compliance readiness scores are much more useful once you have a baseline footprint.
        </Typography>
      </Alert>

      <Typography variant="body2" color="text.secondary" sx={{ mb: 1, maxWidth: 720 }}>
        {PRODUCT_SCOPE_TAGLINE}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3, maxWidth: 720 }}>
        Start with India market requirements. Export frameworks appear when you confirm you sell outside India.
        Formal PDF reports are under{' '}
        <Button component={RouterLink} to="/reporting" size="small" sx={{ verticalAlign: 'baseline' }}>
          Disclosure reports
        </Button>
        .
      </Typography>

      <Alert severity="info" sx={{ mb: 3 }}>
        <Typography variant="body2">{PRODUCT_SCOPE_DISCLAIMER}</Typography>
      </Alert>

      {!exportIntent ? (
        <Paper variant="outlined" sx={{ p: 2.5, mb: 3 }}>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
            Do you export goods or services?
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 640 }}>
            <PlainLanguageLabel termId="cbam">CBAM</PlainLanguageLabel>,{' '}
            <PlainLanguageLabel termId="csrd">CSRD</PlainLanguageLabel>, and buyer audit tools are only relevant if you sell to customers outside India.
            Domestic-only businesses can focus on the India market track.
          </Typography>
          <FormControlLabel
            control={
              <Switch
                checked={exportDraft}
                onChange={(_, checked) => setExportDraft(checked)}
              />
            }
            label="We export goods or services outside India"
          />
          <Box sx={{ mt: 2, display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
            <Button variant="contained" onClick={saveExportIntent} disabled={exportSaving}>
              {exportSaving ? 'Saving…' : 'Save preference'}
            </Button>
            <Button component={RouterLink} to="/msme-profile" size="small">
              Edit in company profile
            </Button>
          </Box>
          {exportFeedback ? (
            <Alert severity="success" sx={{ mt: 2 }}>
              {exportFeedback}
            </Alert>
          ) : null}
        </Paper>
      ) : null}

      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={12} md={exportIntent ? 4 : 6}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                <IndiaIcon color="primary" />
                <Typography variant="subtitle1" fontWeight={600}>
                  India market track
                </Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                BRSR Core, ISO 14064 assurance, MSME ZED certification, PAT intensity, SBTi, product
                footprints, and Indian carbon market alignment.
              </Typography>
            </CardContent>
            <CardActions>
              <Button endIcon={<ArrowForwardIcon />} onClick={() => navigate(complianceSectionHref('/compliance/india', 'overview'))}>
                Open track
              </Button>
            </CardActions>
          </Card>
        </Grid>
        {exportIntent ? (
          <Grid item xs={12} md={4}>
            <Card variant="outlined" sx={{ height: '100%' }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                  <ExportIcon color="primary" />
                  <Typography variant="subtitle1" fontWeight={600}>
                    Global export track
                  </Typography>
                </Box>
                <Typography variant="body2" color="text.secondary">
                  CBAM, CSRD, CDP, TCFD/ISSB, buyer questionnaires, EUDR, and EcoVadis exports.
                </Typography>
              </CardContent>
              <CardActions>
                <Button endIcon={<ArrowForwardIcon />} onClick={() => navigate(complianceSectionHref('/compliance/export', 'overview'))}>
                  Open track
                </Button>
              </CardActions>
            </Card>
          </Grid>
        ) : null}
        <Grid item xs={12} md={exportIntent ? 4 : 6}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                <ReportsIcon color="primary" />
                <Typography variant="subtitle1" fontWeight={600}>
                  Disclosure reports
                </Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                BRSR, ISO 14064, ISO 14067, and CBAM charts and PDF exports for your selected period.
              </Typography>
            </CardContent>
            <CardActions>
              <Button component={RouterLink} to="/reporting" endIcon={<ArrowForwardIcon />}>
                View reports
              </Button>
            </CardActions>
          </Card>
        </Grid>
      </Grid>

      <Card variant="outlined" sx={{ mb: 3, borderColor: 'primary.light' }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
            <GpsIcon color="primary" />
            <Typography variant="subtitle1" fontWeight={600}>
              GPS geotagged site photos
            </Typography>
          </Box>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
            Capture factory, plot, or facility photos on-site with automatic GPS embedded in the image.
            Coordinates feed CBAM, EUDR, ISO assurance, PAT, and buyer compliance agents — no manual entry.
          </Typography>
        </CardContent>
        <CardActions>
          <Button
            component={RouterLink}
            to={GEOTAGGED_EVIDENCE_HREF}
            variant="contained"
            endIcon={<ArrowForwardIcon />}
          >
            Open GPS photo capture
          </Button>
          <Button
            component={RouterLink}
            to={complianceSectionHref('/compliance/export', 'cbam')}
            size="small"
          >
            CBAM site photo
          </Button>
          <Button
            component={RouterLink}
            to={complianceSectionHref('/compliance/india', 'iso-assurance')}
            size="small"
          >
            ISO site photo
          </Button>
        </CardActions>
      </Card>

      {loading && (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
          <CircularProgress />
        </Box>
      )}
      {error && (
        <Alert
          severity="error"
          sx={{ mb: 2 }}
          action={(
            <Button color="inherit" size="small" onClick={() => void load()}>
              Retry
            </Button>
          )}
        >
          {error}
        </Alert>
      )}

      {!loading && overview && (
        <>
          <ComplianceOrchestrationHub
            period="annual"
            exportApplicable={exportApplicable}
            overallScore={overallReadinessScore}
            indiaScore={indiaOverallReadinessScore}
            exportScore={exportOverallReadinessScore}
            onComplete={() => void load()}
            lastRun={agentOrchestration.lastRuns?.reporting_readiness || null}
          />
          <MsmeReadinessChecklist
            prioritizedActions={prioritizedActions}
            moduleGapDetails={moduleGapDetails}
            moduleKeys={readinessModuleKeys}
            overallReadinessScore={overallReadinessScore}
            period="annual"
            exportApplicable={exportApplicable}
            onRefresh={() => void load()}
            layout="hub"
            hideOrchestrationControls={false}
          />

          {supplementalPrioritizedActions.length > 0 ? (
            <Paper variant="outlined" sx={{ p: { xs: 2, sm: 2.5 }, mb: 3, borderColor: 'warning.light' }}>
              <Typography variant="subtitle1" fontWeight={700} sx={{ mb: 0.5 }}>
                Additional fixes
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
                Extra readiness actions not covered in the 3-step checklist above.
              </Typography>
              <ComplianceReadinessActionQueue
                actions={supplementalPrioritizedActions.slice(0, 5)}
                onRefresh={() => void load()}
                period="annual"
                exportApplicable={exportApplicable}
                layout="commandCenter"
              />
            </Paper>
          ) : null}

          <Paper variant="outlined" sx={{ p: { xs: 2, sm: 2.5 }, mb: 3 }}>
            <Typography variant="subtitle1" fontWeight={600} sx={{ mb: 0.5 }}>
              Buyer request inbox
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
              Open buyer audits and supplier questionnaires prioritized by due date and evidence readiness.
            </Typography>
            <Button
              component={RouterLink}
              to="/buyer-audit"
              variant="outlined"
              size="small"
              endIcon={<ArrowForwardIcon />}
              sx={{ mb: 2 }}
            >
              Open buyer audit war room
            </Button>
            <BuyerRequestInbox />
          </Paper>

          {recentOrchestrationRuns.length ? (
            <Box sx={{ mb: 3 }}>
              <Typography variant="subtitle2" fontWeight={700} sx={{ mb: 1 }}>
                Recent readiness checks
              </Typography>
              {recentOrchestrationRuns.slice(0, 3).map((run) => (
                <OrchestrationRunPanel
                  key={`${run.orchestratorType}-${String(run.lastRunAt)}`}
                  lastRun={run}
                  compact
                />
              ))}
            </Box>
          ) : null}

        <Paper variant="outlined" sx={{ p: { xs: 2, sm: 2.5 }, mb: 3 }}>
          <Typography variant="overline" color="text.secondary" display="block" sx={{ mb: 0.5 }}>
            Readiness snapshot
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {String(overview.companyName || 'Your company')} ·{' '}
            <strong>
              {Number(overview.totalEmissionsKgCo2e || 0).toLocaleString('en-IN')} kg CO₂e
            </strong>{' '}
            total inventory (annual period)
            {overallReadinessScore != null ? (
              <>
                {' '}·{' '}
                <strong>{Math.round(overallReadinessScore)}% overall reporting readiness</strong>
                {indiaOverallReadinessScore != null ? (
                  <> (India {Math.round(indiaOverallReadinessScore)}%</>
                ) : null}
                {exportApplicable && exportOverallReadinessScore != null ? (
                  <>, Export {Math.round(exportOverallReadinessScore)}%</>
                ) : null}
                {indiaOverallReadinessScore != null ? <>)</> : null}
              </>
            ) : null}
          </Typography>

          <Divider sx={{ mb: 2.5 }} />

          <Grid container spacing={3}>
            <Grid item xs={12} lg={exportIntent ? 6 : 12}>
              <Typography variant="subtitle2" fontWeight={600} sx={{ mb: 1.5 }}>
                India market
              </Typography>
              <ComplianceReadinessGrid
                compact
                locale={locale}
                items={indiaGridItems}
              />
            </Grid>
            {exportIntent ? (
              <Grid item xs={12} lg={6}>
                <Typography variant="subtitle2" fontWeight={600} sx={{ mb: 1.5 }}>
                  Global export
                </Typography>
                <ComplianceReadinessGrid
                  compact
                  locale={locale}
                  items={exportGridItems}
                />
              </Grid>
            ) : null}
          </Grid>
        </Paper>
        </>
      )}
    </Box>
  );
};

export default ComplianceHubHome;
