import type { NavVisibilityInput } from './appNavigation';

export const getNavUnlockHints = (input: NavVisibilityInput): string[] => {
  const hints: string[] = [];

  if (!input.hasProfile) {
    return [
      'Complete your company profile (step 1 of 4) to unlock document upload, assessments, and compliance tools.',
    ];
  }

  if (!input.hasAssessment) {
    hints.push(
      'Upload bills and run your footprint (steps 2–3 of 4) to unlock offsets, forecasting, and reporting.',
    );
  } else {
    hints.push(
      'Map your operations (step 4 of 4) for consistent reports and buyer filings.',
    );
  }

  if (input.hasProfile && input.hasAssessment && input.hasExportIntent !== true) {
    hints.push('Set export intent in Compliance Hub to unlock CBAM and export compliance tracks.');
  }

  return hints;
};
