import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  FormControl,
  Grid,
  InputAdornment,
  InputLabel,
  LinearProgress,
  MenuItem,
  Paper,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { Calculate as CalculateIcon, PersonAdd as RegisterIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import MarketingHeading from '../shared/MarketingHeading';

/** Indicative India MSME proxies — UI-only, no shared CJS modules. */
const ELECTRICITY_KG_PER_1000_INR = 1.6;
const FUEL_KG_PER_1000_INR = 2.4;

const SECTOR_OPTIONS = [
  { value: 'manufacturing', label: 'Manufacturing', adjustment: -5 },
  { value: 'textiles', label: 'Textiles', adjustment: -5 },
  { value: 'food_processing', label: 'Food processing', adjustment: -3 },
  { value: 'services', label: 'Services', adjustment: 5 },
  { value: 'logistics', label: 'Logistics', adjustment: -8 },
  { value: 'retail', label: 'Retail', adjustment: 0 },
] as const;

const scoreFromIntensity = (intensity: number): number => {
  if (intensity <= 0.5) return 95;
  if (intensity <= 1) return 90;
  if (intensity <= 2) return 85;
  if (intensity <= 5) return 78;
  if (intensity <= 10) return 70;
  if (intensity <= 20) return 60;
  if (intensity <= 50) return 45;
  return Math.max(10, Math.round(45 - Math.log10(intensity / 50) * 20));
};

const scoreLabel = (score: number): string => {
  if (score >= 80) return 'Excellent';
  if (score >= 60) return 'Good';
  if (score >= 40) return 'Average';
  return 'Needs improvement';
};

const scoreColor = (score: number): 'success' | 'warning' | 'error' => {
  if (score >= 60) return 'success';
  if (score >= 40) return 'warning';
  return 'error';
};

const SampleCarbonScoreCalculator: React.FC = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const [electricitySpend, setElectricitySpend] = useState('85000');
  const [fuelSpend, setFuelSpend] = useState('32000');
  const [sector, setSector] = useState<string>('manufacturing');
  const [renewableShare, setRenewableShare] = useState('10');

  const result = useMemo(() => {
    const electricity = Math.max(0, Number(electricitySpend) || 0);
    const fuel = Math.max(0, Number(fuelSpend) || 0);
    const monthlySpend = electricity + fuel;
    const renewable = Math.min(100, Math.max(0, Number(renewableShare) || 0));

    const electricityEmissions = (electricity / 1000) * ELECTRICITY_KG_PER_1000_INR;
    const fuelEmissions = (fuel / 1000) * FUEL_KG_PER_1000_INR;
    const renewableReduction = electricityEmissions * (renewable / 100) * 0.85;
    const totalEmissionsKg = Math.max(0, electricityEmissions + fuelEmissions - renewableReduction);
    const annualizedSpend = monthlySpend > 0 ? monthlySpend * 12 : 100000;
    const intensity = annualizedSpend > 0 ? (totalEmissionsKg * 12 * 1000) / annualizedSpend : 0;

    const sectorAdj = SECTOR_OPTIONS.find((option) => option.value === sector)?.adjustment ?? 0;
    const renewableBonus = renewable > 50 ? 5 : 0;
    const carbonScore = Math.max(
      0,
      Math.min(100, Math.round(scoreFromIntensity(intensity) + sectorAdj + renewableBonus))
    );

    return {
      carbonScore,
      totalEmissionsKg,
      monthlySpend,
      intensity: annualizedSpend > 0 ? (totalEmissionsKg / (monthlySpend || 1)) * 1000 : 0,
    };
  }, [electricitySpend, fuelSpend, renewableShare, sector]);

  return (
    <Paper
      elevation={0}
      sx={{
        p: { xs: 2.5, md: 3.5 },
        borderRadius: 3,
        border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.35 : 0.22)}`,
        bgcolor: alpha(theme.palette.primary.main, isDark ? 0.08 : 0.04),
      }}
    >
      <Stack spacing={2.5}>
        <Box>
          <MarketingHeading level="h3" sx={{ mb: 1 }}>
            Estimate your MSME carbon score
          </MarketingHeading>
          <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.7, maxWidth: 720 }}>
            Enter monthly energy spend for a quick illustrative score. Register to replace this estimate with
            bill-backed Scope 1–2 totals.
          </Typography>
        </Box>

        <Grid container spacing={2}>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              fullWidth
              label="Monthly electricity spend"
              type="number"
              value={electricitySpend}
              onChange={(event) => setElectricitySpend(event.target.value)}
              InputProps={{
                startAdornment: <InputAdornment position="start">₹</InputAdornment>,
              }}
              inputProps={{ min: 0 }}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              fullWidth
              label="Monthly fuel spend"
              type="number"
              value={fuelSpend}
              onChange={(event) => setFuelSpend(event.target.value)}
              InputProps={{
                startAdornment: <InputAdornment position="start">₹</InputAdornment>,
              }}
              inputProps={{ min: 0 }}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <FormControl fullWidth>
              <InputLabel id="sample-sector-label">Business sector</InputLabel>
              <Select
                labelId="sample-sector-label"
                label="Business sector"
                value={sector}
                onChange={(event) => setSector(event.target.value)}
              >
                {SECTOR_OPTIONS.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              fullWidth
              label="Renewable energy share"
              type="number"
              value={renewableShare}
              onChange={(event) => setRenewableShare(event.target.value)}
              InputProps={{
                endAdornment: <InputAdornment position="end">%</InputAdornment>,
              }}
              inputProps={{ min: 0, max: 100 }}
            />
          </Grid>
        </Grid>

        <Grid container spacing={2} alignItems="stretch">
          <Grid item xs={12} md={5}>
            <Paper
              variant="outlined"
              sx={{
                height: '100%',
                p: 2.5,
                borderRadius: 2.5,
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                textAlign: 'center',
              }}
            >
              <Typography variant="overline" color="text.secondary" sx={{ fontWeight: 700 }}>
                Illustrative carbon score
              </Typography>
              <Typography
                variant="h2"
                sx={{
                  fontWeight: 800,
                  lineHeight: 1,
                  my: 1,
                  color: `${scoreColor(result.carbonScore)}.main`,
                }}
              >
                {result.carbonScore}
              </Typography>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                {scoreLabel(result.carbonScore)}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={result.carbonScore}
                color={scoreColor(result.carbonScore)}
                sx={{ width: '100%', height: 8, borderRadius: 1, mb: 1.5 }}
              />
              <Typography variant="caption" color="text.secondary">
                Based on spend intensity — not a verified assessment.
              </Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} md={7}>
            <Stack spacing={1.25} sx={{ height: '100%', justifyContent: 'center' }}>
              <Typography variant="body2" color="text.secondary">
                <strong>Estimated monthly emissions:</strong> {result.totalEmissionsKg.toFixed(1)} kg CO₂e
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Monthly energy spend:</strong> ₹{result.monthlySpend.toLocaleString('en-IN')}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Emission intensity:</strong> {result.intensity.toFixed(2)} kg CO₂e per ₹1,000 spent
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ pt: 0.5 }}>
                Upload electricity and fuel bills after registration for document-backed Scope 1–2 totals and
                buyer-ready reports.
              </Typography>
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.25} sx={{ pt: 1 }}>
                <Button
                  component={RouterLink}
                  to="/register?type=msme"
                  variant="contained"
                  startIcon={<RegisterIcon />}
                  sx={{ textTransform: 'none', fontWeight: 700 }}
                >
                  Register your MSME
                </Button>
                <Button
                  component={RouterLink}
                  to="/login"
                  variant="outlined"
                  startIcon={<CalculateIcon />}
                  sx={{ textTransform: 'none', fontWeight: 600 }}
                >
                  Sign in for full assessment
                </Button>
              </Stack>
            </Stack>
          </Grid>
        </Grid>
      </Stack>
    </Paper>
  );
};

export default SampleCarbonScoreCalculator;
