import React from 'react';
import {
  Box,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { TableChart as TableChartIcon } from '@mui/icons-material';
import type { EmissionSourceRow, ScopeSplitRow } from './DashboardEmissionsCharts';

const visuallyHiddenSx = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  whiteSpace: 'nowrap',
  border: 0,
} as const;

interface EmissionsChartDataTableProps {
  chartView: 'source' | 'scope';
  emissionSourceBarData: EmissionSourceRow[];
  scopeSplitBarData: ScopeSplitRow[];
  showDataTable: boolean;
  onToggleDataTable: () => void;
}

const renderSourceTable = (rows: EmissionSourceRow[]) => (
  <Table size="small" aria-label="Emissions by activity source">
    <caption style={{ captionSide: 'top', textAlign: 'left', paddingBottom: 8 }}>
      Emissions by activity source (tCO₂e)
    </caption>
    <TableHead>
      <TableRow>
        <TableCell component="th" scope="col">
          Source
        </TableCell>
        <TableCell component="th" scope="col" align="right">
          kg CO₂e
        </TableCell>
        <TableCell component="th" scope="col" align="right">
          tCO₂e
        </TableCell>
      </TableRow>
    </TableHead>
    <TableBody>
      {rows.map((row) => (
        <TableRow key={row.name}>
          <TableCell component="th" scope="row">
            {row.name}
          </TableCell>
          <TableCell align="right">{row.kg.toLocaleString('en-IN')}</TableCell>
          <TableCell align="right">{row.tCO2e.toFixed(2)}</TableCell>
        </TableRow>
      ))}
    </TableBody>
  </Table>
);

const renderScopeTable = (rows: ScopeSplitRow[]) => (
  <Table size="small" aria-label="Emissions by GHG scope">
    <caption style={{ captionSide: 'top', textAlign: 'left', paddingBottom: 8 }}>
      Emissions by GHG Protocol scope (tCO₂e)
    </caption>
    <TableHead>
      <TableRow>
        <TableCell component="th" scope="col">
          Scope
        </TableCell>
        <TableCell component="th" scope="col" align="right">
          kg CO₂e
        </TableCell>
        <TableCell component="th" scope="col" align="right">
          tCO₂e
        </TableCell>
      </TableRow>
    </TableHead>
    <TableBody>
      {rows.map((row) => (
        <TableRow key={row.name}>
          <TableCell component="th" scope="row">
            {row.name}
          </TableCell>
          <TableCell align="right">{row.kg.toLocaleString('en-IN')}</TableCell>
          <TableCell align="right">{row.tCO2e.toFixed(2)}</TableCell>
        </TableRow>
      ))}
    </TableBody>
  </Table>
);

export const EmissionsChartDataTable: React.FC<EmissionsChartDataTableProps> = ({
  chartView,
  emissionSourceBarData,
  scopeSplitBarData,
  showDataTable,
  onToggleDataTable,
}) => {
  const activeRows = chartView === 'source' ? emissionSourceBarData : scopeSplitBarData;
  if (activeRows.length === 0) return null;

  const tableId = chartView === 'source' ? 'emissions-source-data-table' : 'emissions-scope-data-table';
  const tableContent =
    chartView === 'source'
      ? renderSourceTable(emissionSourceBarData)
      : renderScopeTable(scopeSplitBarData);

  return (
    <Box sx={{ mt: 2 }} role="region" aria-label="Chart data table">
      <Button
        size="small"
        variant="text"
        startIcon={<TableChartIcon />}
        onClick={onToggleDataTable}
        aria-expanded={showDataTable}
        aria-controls={tableId}
      >
        {showDataTable ? 'Hide data table' : 'Show data table'}
      </Button>
      <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
        Accessible tabular view of the chart data for screen readers and keyboard users.
      </Typography>
      <TableContainer
        id={tableId}
        sx={{
          mt: 1,
          ...(showDataTable ? {} : visuallyHiddenSx),
        }}
      >
        {tableContent}
      </TableContainer>
    </Box>
  );
};

export default EmissionsChartDataTable;
